QStringList SettingsDialog::getVisibleSidebarFeatures() const
{
    QStringList visible;
    for (const QString &name : m_sidebarFeatureNames)
    {
        const auto it = m_sidebarSwitches.constFind(name);
        if (it != m_sidebarSwitches.cend() && it.value()->isChecked())
        {
            visible.append(name);
        }
    }
    return visible;
}

void SettingsDialog::refreshSidebarSelectionCount()
{
    if (m_sidebarSelectionCountLabel)
    {
        m_sidebarSelectionCountLabel->setText(
            tr("已启用 %1 个功能").arg(getVisibleSidebarFeatures().size()));
    }
}

void SettingsDialog::showSidebarSelectionWarning(const QString &message)
{
    if (m_sidebarToast)
    {
        QPointer<QFrame> oldToast = m_sidebarToast;
        m_sidebarToast = nullptr;
        oldToast->close();
        oldToast->deleteLater();
    }

    QLabel *label = new QLabel(this);
    label->setText(message);
    label->setAlignment(Qt::AlignCenter);
    label->setWordWrap(true);
    label->setMaximumWidth(600);

    const bool darkTheme = palette().color(QPalette::Window).lightness() < 128;

    QString bgColor;
    QString textColor;
    QString borderColor;

    if (darkTheme)
    {
        bgColor = "#8B0000";
        textColor = "white";
        borderColor = "#FF6B6B";
    }
    else
    {
        bgColor = "#dc3545";
        textColor = "white";
        borderColor = "#ff6b6b";
    }

    label->setStyleSheet(QString(
                             "QLabel {"
                             "    background-color: %1;"
                             "    color: %2;"
                             "    font-size: 14px;"
                             "    font-weight: bold;"
                             "    padding: 10px 20px;"
                             "    border-radius: 8px;"
                             "    border: 2px solid %3;"
                             "}")
                             .arg(bgColor, textColor, borderColor));
    label->adjustSize();

    const int x = width() - label->width() - 20;
    const int y = 20;
    label->move(x, y);
    label->raise();
    label->show();

    QGraphicsOpacityEffect *effect = new QGraphicsOpacityEffect(label);
    label->setGraphicsEffect(effect);

    QPropertyAnimation *fadeIn = new QPropertyAnimation(effect, "opacity", label);
    fadeIn->setDuration(300);
    fadeIn->setStartValue(0.0);
    fadeIn->setEndValue(1.0);
    fadeIn->setEasingCurve(QEasingCurve::OutCubic);
    fadeIn->start(QAbstractAnimation::DeleteWhenStopped);

    QTimer::singleShot(2700, label, [label, effect]()
    {
        if (!label)
        {
            return;
        }

        QPropertyAnimation *fadeOut = new QPropertyAnimation(effect, "opacity", label);
        fadeOut->setDuration(300);
        fadeOut->setStartValue(1.0);
        fadeOut->setEndValue(0.0);
        fadeOut->setEasingCurve(QEasingCurve::InCubic);
        QObject::connect(fadeOut, &QPropertyAnimation::finished, label, &QLabel::deleteLater);
        fadeOut->start(QAbstractAnimation::DeleteWhenStopped);
    });

    m_sidebarToast = label;
}

void SettingsDialog::loadCustomCompletions()
{
    QSettings settings("CompilerIDE", "Compiler IDE 2.8.6");
    QStringList items = settings.value("CustomCompletions", QStringList()).toStringList();
    customCompletionList->clear();
    customCompletionList->addItems(items);
}

void SettingsDialog::saveCustomCompletions()
{
    QStringList items;
    for (int i = 0; i < customCompletionList->count(); ++i)
    {
        items.append(customCompletionList->item(i)->text());
    }
    QSettings settings("CompilerIDE", "Compiler IDE 2.8.6");
    settings.setValue("CustomCompletions", items);
}

void SettingsDialog::addCustomCompletion()
{
    QString text = newCompletionEdit->text().trimmed();
    if (text.isEmpty())
    {
        return;
    }

    QList<QListWidgetItem *> found = customCompletionList->findItems(text, Qt::MatchExactly);
    if (found.isEmpty())
    {
        customCompletionList->addItem(text);
        newCompletionEdit->clear();
        customCompletionList->scrollToBottom();
    }
    else
    {
        QMessageBox::warning(this, tr("提示"), tr("该补全词条已存在！"));
    }
}

void SettingsDialog::removeCustomCompletion()
{
    QList<QListWidgetItem *> selected = customCompletionList->selectedItems();
    for (QListWidgetItem *item : selected)
    {
        delete customCompletionList->takeItem(customCompletionList->row(item));
    }
}

void SettingsDialog::addCustomCompileCommand()
{
    if (!compileCommandCombo || !newCompileCommandEdit)
    {
        return;
    }

    const QString command = newCompileCommandEdit->text().trimmed();
    if (command.isEmpty())
    {
        return;
    }

    int existingIndex = compileCommandCombo->findData(command);
    if (existingIndex < 0)
    {
        compileCommandCombo->addItem(command, command);
        existingIndex = compileCommandCombo->count() - 1;
    }

    compileCommandCombo->setCurrentIndex(existingIndex);
    newCompileCommandEdit->clear();
}

void SettingsDialog::removeCustomCompileCommand()
{
    if (!compileCommandCombo)
    {
        return;
    }

    const int index = compileCommandCombo->currentIndex();
    if (index <= 0)
    {
        return;
    }

    compileCommandCombo->removeItem(index);
    compileCommandCombo->setCurrentIndex(0);
}

QStringList SettingsDialog::getCustomCompileCommands() const
{
    QStringList commands;
    if (!compileCommandCombo)
    {
        return commands;
    }

    for (int i = 1; i < compileCommandCombo->count(); ++i)
    {
        const QString command = compileCommandCombo->itemData(i).toString().trimmed();
        if (!command.isEmpty() && !commands.contains(command))
        {
            commands.append(command);
        }
    }
    return commands;
}

QString SettingsDialog::getCurrentCustomCompileCommand() const
{
    if (!compileCommandCombo || compileCommandCombo->currentIndex() <= 0)
    {
        return QString();
    }
    return compileCommandCombo->currentData().toString().trimmed();
}

