bool CodeEditor::isInCommentOrStringForBeautify(const QString &text, int position) const
{
    if (position < 0 || position >= text.length())
    {
        return false;
    }

    bool inString = false;
    bool inChar = false;
    bool inBlockComment = false;
    bool escaped = false;

    for (int i = 0; i < position; ++i)
    {
        QChar c = text[i];

        if (escaped)
        {
            escaped = false;
            continue;
        }

        if (c == '\\')
        {
            escaped = true;
            continue;
        }

        if (!inBlockComment && !inString && !inChar && c == '/' && i + 1 < text.length() && text[i + 1] == '/')
        {
            return true;
        }

        if (!inString && !inChar)
        {
            if (!inBlockComment && c == '/' && i + 1 < text.length() && text[i + 1] == '*')
            {
                inBlockComment = true;
                i++;
                continue;
            }
            if (inBlockComment && c == '*' && i + 1 < text.length() && text[i + 1] == '/')
            {
                inBlockComment = false;
                i++;
                continue;
            }
        }

        if (!inBlockComment)
        {
            if (c == '"' && !inChar)
            {
                inString = !inString;
            }
            else if (c == '\'' && !inString)
            {
                inChar = !inChar;
            }
        }
    }

    return inString || inChar || inBlockComment;
}

bool CodeEditor::isControlStructureLine(const QString &line) const
{
    QString trimmed = line.trimmed();

    QRegularExpression controlPattern(
        R"(^\s*(if|else\s+if|else|for|while|switch|do)\s*\()");

    QRegularExpression funcPattern(
        R"(^\s*((?:void|int|char|double|float|bool|long|short|unsigned|signed|auto|inline|static|const|virtual)\s+)+\w+\s*\()");

    QRegularExpression methodPattern(
        R"(^\s*\w+\s*::\s*\w+\s*\()");

    return controlPattern.match(trimmed).hasMatch() ||
           funcPattern.match(trimmed).hasMatch() ||
           methodPattern.match(trimmed).hasMatch();
}

QString CodeEditor::beautifyCode(const QString &code, bool isControlStructure)
{
    QString result = code;

    QList<QString> protectedPointers;
    int pointerIndex = 0;
    int maxIterations = 100;

    for (int iter = 0; iter < maxIterations; iter++)
    {
        QRegularExpression ptrPattern(R"(\b([a-zA-Z_][a-zA-Z0-9_]*)\s+\*\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*[,;)])");
        QRegularExpressionMatch match = ptrPattern.match(result);
        if (!match.hasMatch())
        {
            break;
        }

        QString typeName = match.captured(1);
        QString varName = match.captured(2);
        QString placeholder = QString("__PTR_%1__").arg(pointerIndex++);
        QString replacement = typeName + " " + placeholder + varName + match.captured(0).right(1);
        result.replace(match.capturedStart(), match.capturedLength(), replacement);
        protectedPointers.append(placeholder);
    }

    for (int iter = 0; iter < maxIterations; iter++)
    {
        QRegularExpression ptrCommaPattern(R"(,\s*\*\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*[,;)])");
        QRegularExpressionMatch match = ptrCommaPattern.match(result);
        if (!match.hasMatch())
        {
            break;
        }

        QString varName = match.captured(1);
        QString placeholder = QString("__PTR_%1__").arg(pointerIndex++);
        QString replacement = ", " + placeholder + varName + match.captured(0).right(1);
        result.replace(match.capturedStart(), match.capturedLength(), replacement);
        protectedPointers.append(placeholder);
    }

    for (int iter = 0; iter < maxIterations; ++iter)
    {
        QRegularExpression ptrParenPattern(R"(\(\s*([a-zA-Z_][a-zA-Z0-9_]*)\s+\*\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\))");
        QRegularExpressionMatch match = ptrParenPattern.match(result);
        if (!match.hasMatch())
        {
            break;
        }

        QString typeName = match.captured(1);
        QString varName = match.captured(2);
        QString placeholder = QString("__PTR_%1__").arg(pointerIndex++);
        QString replacement = "(" + typeName + " " + placeholder + varName + ")";
        result.replace(match.capturedStart(), match.capturedLength(), replacement);
        protectedPointers.append(placeholder);
    }

    QList<QString> protectedStrings;
    QRegularExpression stringPattern(R"("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')");
    QRegularExpressionMatchIterator it = stringPattern.globalMatch(result);

    QList<QRegularExpressionMatch> matches;
    while (it.hasNext())
    {
        matches.prepend(it.next());
    }

    for (const auto &match : matches)
    {
        protectedStrings.append(match.captured());
        result.replace(match.capturedStart(), match.capturedLength(),
                       QString("__STR_%1__").arg(protectedStrings.size() - 1));
    }

    result.replace(QRegularExpression(">(\\s+)\\("), ">(");

    QList<QString> protectedTemplates;
    int templateIndex = 0;

    for (int iter = 0; iter < maxIterations; iter++)
    {
        QRegularExpression templatePattern(R"(\b([a-zA-Z_][a-zA-Z0-9_]*)\s*<([^<>&|;]*)>)");
        QRegularExpressionMatch match = templatePattern.match(result);

        if (!match.hasMatch())
        {
            break;
        }

        QString templateName = match.captured(1);
        QString templateArgs = match.captured(2);

        QString processedArgs = templateArgs.trimmed();
        processedArgs.replace(QRegularExpression("\\s+"), " ");
        processedArgs.replace(QRegularExpression("\\s*,\\s*"), ", ");

        QString processedTemplate = templateName + "<" + processedArgs + ">";

        QString placeholder = QString("__TMPL_%1__").arg(templateIndex++);
        protectedTemplates.append(processedTemplate);
        result.replace(match.capturedStart(), match.capturedLength(), placeholder);
    }

    QList<QString> protectedComments;
    QRegularExpression commentPattern(R"(//.*$|/\*.*?\*/)");
    QRegularExpressionMatchIterator commentIt = commentPattern.globalMatch(result);

    QList<QRegularExpressionMatch> commentMatches;
    while (commentIt.hasNext())
    {
        commentMatches.prepend(commentIt.next());
    }

    for (const auto &match : commentMatches)
    {
        protectedComments.append(match.captured());
        result.replace(match.capturedStart(), match.capturedLength(),
                       QString("__CMT_%1__").arg(protectedComments.size() - 1));
    }

    result.replace(QRegularExpression(R"(\bif\s*\()"), "if (");
    result.replace(QRegularExpression(R"(\bfor\s*\()"), "for (");
    result.replace(QRegularExpression(R"(\bwhile\s*\()"), "while (");
    result.replace(QRegularExpression(R"(\bswitch\s*\()"), "switch (");
    result.replace(QRegularExpression(R"(\bcatch\s*\()"), "catch (");

    int searchPos = 0;
    while (true)
    {
        int forPos = result.indexOf(QRegularExpression("\\bfor\\b"), searchPos);
        if (forPos == -1)
        {
            break;
        }

        int leftParen = -1;
        for (int i = forPos + 3; i < result.length(); i++)
        {
            if (result[i] == '(')
            {
                leftParen = i;
                break;
            }
            if (!result[i].isSpace())
            {
                break;
            }
        }

        if (leftParen == -1)
        {
            searchPos = forPos + 3;
            continue;
        }

        int parenCount = 1;
        int rightParen = leftParen + 1;
        while (rightParen < result.length() && parenCount > 0)
        {
            if (result[rightParen] == '(')
            {
                parenCount++;
            }
            else if (result[rightParen] == ')')
            {
                parenCount--;
            }
            rightParen++;
        }
        rightParen--;

        if (parenCount != 0)
        {
            searchPos = forPos + 3;
            continue;
        }

        for (int i = leftParen + 1; i < rightParen; i++)
        {
            if (result[i] == ';')
            {
                if (i + 1 >= rightParen)
                {
                    continue;
                }

                QChar next = result[i + 1];
                if (next == ';' || next == ')' || next == ']' || next == '}' || next == ',' || next.isSpace())
                {
                    continue;
                }

                result.insert(i + 1, ' ');
                rightParen++;
            }
        }
        searchPos = rightParen + 1;
    }

    result.replace("++", "__INCR__");
    result.replace("--", "__DECR__");
    result.replace("->", "__ARROW__");
    result.replace("<<", "__LSHIFT__");
    result.replace(">>", "__RSHIFT__");
    result.replace("::", "__SCOPE__");

    result.replace(QRegularExpression("(\\w)\\s*\\+\\+"), "\\1++");
    result.replace(QRegularExpression("(\\w)\\s*\\-\\-"), "\\1--");
    result.replace(QRegularExpression("\\+\\+\\s*(\\w)"), "++\\1");
    result.replace(QRegularExpression("\\-\\-\\s*(\\w)"), "--\\1");

    QList<QString> protectedCompoundOps;
    QStringList compoundOps = {"+=", "-=", "*=", "/=", "%=", "&=", "|=", "^="};
    int compoundIndex = 0;

    for (const QString &op : compoundOps)
    {
        QRegularExpression opPattern(QString("\\s*%1\\s*").arg(QRegularExpression::escape(op)));
        QRegularExpressionMatchIterator opIt = opPattern.globalMatch(result);

        QList<QRegularExpressionMatch> opMatches;
        while (opIt.hasNext())
        {
            opMatches.prepend(opIt.next());
        }

        for (const auto &match : opMatches)
        {
            QString formattedOp = QString(" %1 ").arg(op);
            QString placeholder = QString("__COMPOP_%1__").arg(compoundIndex++);
            protectedCompoundOps.append(formattedOp);
            result.replace(match.capturedStart(), match.capturedLength(), placeholder);
        }
    }

    QStringList compareOps = {"<=", ">=", "==", "!="};
    for (const QString &op : compareOps)
    {
        QRegularExpression opPattern(QString("\\s*%1\\s*").arg(QRegularExpression::escape(op)));
        result.replace(opPattern, QString(" %1 ").arg(op));
    }

    result.replace(QRegularExpression("\\s*&&\\s*"), " && ");
    result.replace(QRegularExpression("\\s*\\|\\|\\s*"), " || ");

    result.replace(QRegularExpression("\\s*\\?\\s*"), " ? ");
    result.replace(QRegularExpression("\\s*:\\s*"), " : ");

    QString prevResult;
    int loopCount = 0;
    do
    {
        prevResult = result;
        result.replace(QRegularExpression("([^\\s<>=_])\\s*<\\s*([^\\s<>=_])"), "\\1 < \\2");
        result.replace(QRegularExpression("([^\\s<>=_])\\s*>\\s*([^\\s<>=_])"), "\\1 > \\2");
    } while (result != prevResult && ++loopCount < 10);

    loopCount = 0;
    do
    {
        prevResult = result;
        result.replace(QRegularExpression("([a-zA-Z0-9_\$\$])&([a-zA-Z0-9_(])"), "\\1 & \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\$\$])\\|([a-zA-Z0-9_(])"), "\\1 | \\2");
        result.replace(QRegularExpression(R"(([a-zA-Z0-9_)\]\}])\s*\^\s*([a-zA-Z0-9_(\[]))"), "\\1 ^ \\2");
    } while (result != prevResult && ++loopCount < 10);

    result.replace(QRegularExpression("\\s*\\+\\s*"), "+");
    result.replace(QRegularExpression("\\s*\\-\\s*"), "-");
    result.replace(QRegularExpression("\\s*\\*\\s*"), "*");
    result.replace(QRegularExpression("\\s*\\/\\s*"), "/");
    result.replace(QRegularExpression("\\s*%\\s*"), "%");

    loopCount = 0;
    do
    {
        prevResult = result;
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\]])\\+([a-zA-Z0-9_(])"), "\\1 + \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9)\\]])-([a-zA-Z0-9_(])"), "\\1 - \\2");
        result.replace(QRegularExpression("([><=!])-([a-zA-Z0-9_(])"), "\\1 -\\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\]])\\*([a-zA-Z0-9_(])"), "\\1 * \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\]])\\/([a-zA-Z0-9_(])"), "\\1 / \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\]])%([a-zA-Z0-9_(])"), "\\1 % \\2");
    } while (result != prevResult && ++loopCount < 10);

    loopCount = 0;
    do
    {
        prevResult = result;
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\])])\\+([a-zA-Z0-9_(])"), "\\1 + \\2");
        result.replace(QRegularExpression("([><=!])-([a-zA-Z0-9_(])"), "\\1 -\\2");
        result.replace(QRegularExpression("([a-zA-Z0-9)\\]])-([a-zA-Z0-9_(])"), "\\1 - \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\])])\\*([a-zA-Z0-9_(])"), "\\1 * \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\])])\\/([a-zA-Z0-9_(])"), "\\1 / \\2");
        result.replace(QRegularExpression("([a-zA-Z0-9_\\$\\$_\\])])%([a-zA-Z0-9_(])"), "\\1 % \\2");
    } while (result != prevResult && ++loopCount < 10);

    int assignLoopCount = 0;
    do
    {
        prevResult = result;
        QRegularExpression assignPattern("([^=!<>+\\-*/%&|^_])=([^=])");
        result.replace(assignPattern, "\\1 = \\2");
    } while (result != prevResult && ++assignLoopCount < 10);

    result.replace(QRegularExpression("(?<![=!<>+\\-*/%&|^\\s])=(?![=\\s])"), " = ");

    result.replace(QRegularExpression(",\\s*"), ", ");

    result.replace("__INCR__", "++");
    result.replace("__DECR__", "--");
    result.replace("__ARROW__", "->");
    result.replace("__LSHIFT__", " << ");
    result.replace("__RSHIFT__", " >> ");
    result.replace("__SCOPE__", "::");

    for (int i = 0; i < protectedCompoundOps.size(); i++)
    {
        result.replace(QString("__COMPOP_%1__").arg(i), protectedCompoundOps[i]);
    }

    result.replace(QRegularExpression(",(?!\\s)"), ", ");
    result.replace(QRegularExpression(",\\s{2,}"), ", ");

    result.replace(QRegularExpression("  +"), " ");

    QStringList pointerKeywords =
        {
            "void", "int", "char", "double", "float", "bool", "long", "short",
            "signed", "unsigned", "auto", "wchar_t", "size_t",
            "class", "struct", "typename", "virtual", "const", "static"};
    QString typePattern = pointerKeywords.join("|");
    result.replace(QRegularExpression(QString("\\b(%1)\\s+\\*\\s+([a-zA-Z_][a-zA-Z0-9_]*)").arg(typePattern)), "\\1 *\\2");

    result.replace(QRegularExpression("(^|[;{}]\\s*)([a-zA-Z_][a-zA-Z0-9_]*)\\s+\\*\\s+([a-zA-Z_][a-zA-Z0-9_]*)"), "\\1\\2 *\\3");

    result.replace(QRegularExpression(",\\s*\\*\\s+([a-zA-Z_][a-zA-Z0-9_]*)"), ", *\\1");

    result.replace(QRegularExpression("\\(\\s*([a-zA-Z_][a-zA-Z0-9_]*)\\s+\\*\\s+([a-zA-Z_][a-zA-Z0-9_]*)"), "(\\1 *\\2");
    result.replace(QRegularExpression(",\\s+([a-zA-Z_][a-zA-Z0-9_]*)\\s+\\*\\s+([a-zA-Z_][a-zA-Z0-9_]*)"), ", \\1 *\\2");

    result.replace(QRegularExpression("([a-zA-Z0-9_\\]])\\s*\\.\\s*([a-zA-Z_])"), "\\1.\\2");

    result.replace(QRegularExpression("\\(\\s*\\)"), "()");
    result.replace(QRegularExpression("\\)\\s*([);,])"), ")\\1");

    result.replace(QRegularExpression("\\b([a-zA-Z0-9_]+)\\*([a-zA-Z0-9_]+)\\b"), "\\1 * \\2");

    result.replace(QRegularExpression("([a-zA-Z0-9_)\\]\\}])\\s*\\*\\s*([a-zA-Z0-9_(\\[])"), "\\1 * \\2");

    // Final multiplicative-operator normalization. Pointer declarations are still protected
    // by __PTR_n__ placeholders here, so this only targets operand-to-operand operators.
    result.replace(QRegularExpression(R"(([a-zA-Z0-9_)\]\}])\s*([*/%])\s*([a-zA-Z0-9_(\[]))"), "\\1 \\2 \\3");

    for (int i = 0; i < protectedComments.size(); i++)
    {
        result.replace(QString("__CMT_%1__").arg(i), protectedComments[i]);
    }

    for (int i = protectedTemplates.size() - 1; i >= 0; i--)
    {
        result.replace(QString("__TMPL_%1__").arg(i), protectedTemplates[i]);
    }

    for (int i = 0; i < protectedStrings.size(); i++)
    {
        result.replace(QString("__STR_%1__").arg(i), protectedStrings[i]);
    }

    for (int i = 0; i < protectedPointers.size(); i++)
    {
        result.replace(protectedPointers[i], "*");
    }

    return result;
}

void CodeEditor::beautifyCurrentLine()
{
    if (!codeBeautify)
    {
        return;
    }

    QTextCursor cursor = textCursor();
    QTextBlock block = cursor.block();
    QString lineText = block.text();

    QString indent;
    for (int i = 0; i < lineText.length(); ++i)
    {
        if (lineText[i].isSpace())
        {
            indent += lineText[i];
        }
        else
        {
            break;
        }
    }

    QString trimmedLine = lineText.trimmed();

    if (trimmedLine.startsWith("//") || trimmedLine.startsWith("/*"))
    {
        return;
    }

    bool isControlStructure = isControlStructureLine(lineText);

    QString beautified = beautifyCode(trimmedLine, isControlStructure);

    if (beautified == trimmedLine)
    {
        return;
    }

    cursor.movePosition(QTextCursor::StartOfBlock);
    cursor.movePosition(QTextCursor::EndOfBlock, QTextCursor::KeepAnchor);

    cursor.insertText(indent + beautified);
}

bool CodeEditor::eventFilter(QObject *obj, QEvent *event)
{
    // QPlainTextEdit inherits QAbstractScrollArea; mouse input is physically
    // delivered to viewport().  Keep a viewport filter in addition to the
    // remapped mouseMoveEvent() so hover diagnostics remain reliable across
    // Qt/platform style changes.
    if (obj == viewport())
    {
        if (event->type() == QEvent::MouseMove)
        {
            QMouseEvent *mouseEvent = static_cast<QMouseEvent *>(event);
            if (mouseEvent->buttons() == Qt::NoButton &&
                !(completionPopup && completionPopup->isVisible()))
            {
                const QPoint viewportPos = mouseEvent->position().toPoint();
                const QList<DiagnosticInfo> diagnostics = diagnosticsAtViewportPoint(viewportPos);
                if (!diagnostics.isEmpty())
                {
                    scheduleDiagnosticHover(diagnostics, mouseEvent->globalPosition().toPoint());
                }
                else
                {
                    hideDiagnosticHoverPopup();
                }
            }
            else
            {
                hideDiagnosticHoverPopup();
            }
        }
        else if (event->type() == QEvent::Leave)
        {
            hideDiagnosticHoverPopup();
        }
    }

    if (obj == completionList && completionPopup->isVisible())
    {
        if (event->type() == QEvent::KeyPress)
        {
            QKeyEvent *keyEvent = static_cast<QKeyEvent *>(event);

            if (acceptsCompletionWithKey(keyEvent))
            {
                QModelIndex index = completionList->currentIndex();
                if (index.isValid())
                {
                    insertCompletion(index.data().toString());
                }
                return true;
            }
            else if (keyEvent->key() == Qt::Key_Escape)
            {
                hideCompletion();
                this->setFocus(Qt::OtherFocusReason);
                return true;
            }
            else if (keyEvent->key() == Qt::Key_Up || keyEvent->key() == Qt::Key_Down)
            {
                return false;
            }
            else if (keyEvent->key() == Qt::Key_Tab ||
                     keyEvent->key() == Qt::Key_Return ||
                     keyEvent->key() == Qt::Key_Enter ||
                     keyEvent->key() == Qt::Key_Space)
            {
                hideCompletion();
                this->setFocus(Qt::OtherFocusReason);
                return false;
            }
            else
            {
                hideCompletion();
                this->setFocus(Qt::OtherFocusReason);
                return false;
            }
        }
    }

    return QPlainTextEdit::eventFilter(obj, event);
}

void CodeEditor::setCodeFoldingEnabled(bool enabled)
{
    updateLineNumberAreaWidth(0);
    update();
}

void CodeEditor::setLineNumbersEnabled(bool enabled)
{
    lineNumbers = enabled;
    lineNumberArea->setVisible(true);
    updateLineNumberAreaWidth(0);
    update();
}

void CodeEditor::setDarkThemeEnabled(bool enabled)
{
    setThemeMode(enabled ? ThemeMode::Dark : ThemeMode::Light);
}

void CodeEditor::setThemeMode(ThemeMode mode)
{
    themeMode = mode;
    darkTheme = mode == ThemeMode::Dark;

    const bool eyeCare = mode == ThemeMode::EyeCare;

const QColor baseColor =
        darkTheme ? QColor("#1E1E1E")
                  : eyeCare ? QColor("#FDF6E3")
                            : QColor("#FFFFFF");

    const QColor textColor =
        darkTheme ? QColor("#DCDCDC")
                  : eyeCare ? QColor("#3B3A32")
                            : QColor("#000000");

    const QColor selectionColor =
        darkTheme ? QColor("#2A82DA")
                  : eyeCare ? QColor("#B8D7A3")
                            : QColor("#0078D7");

    const QColor selectedTextColor =
        darkTheme ? QColor("#000000")
                  : QColor("#FFFFFF");

    if (darkTheme)
    {
        errorBgColor = QColor(80, 40, 40);
        warningBgColor = QColor(80, 70, 40);
        lineNumberArea->setStyleSheet(
            "background: #2D2D2D; color: #888888;");
    }
    else if (eyeCare)
    {
        errorBgColor = QColor("#F1D1C8");
        warningBgColor = QColor("#F3E3B3");
        lineNumberArea->setStyleSheet(
            "background: #E9DDBB; color: #555A48;");
    }
    else
    {
        errorBgColor = QColor(255, 230, 230);
        warningBgColor = QColor(255, 245, 220);
        lineNumberArea->setStyleSheet(
            "background: #F5F5F5; color: #666666;");
    }

    QPalette editorPalette = palette();
    editorPalette.setColor(QPalette::Base, baseColor);
    editorPalette.setColor(QPalette::Window, baseColor);
    editorPalette.setColor(QPalette::Text, textColor);
    editorPalette.setColor(QPalette::WindowText, textColor);
    editorPalette.setColor(QPalette::Highlight, selectionColor);
    editorPalette.setColor(QPalette::HighlightedText, selectedTextColor);
    setPalette(editorPalette);

    if (viewport())
    {
        viewport()->setPalette(editorPalette);
        viewport()->setAutoFillBackground(true);
    }

    if (m_largeDocumentMode)
    {
        if (!styleSheet().isEmpty())
        {
            setStyleSheet(QString());
        }
    }
    else
    {
        setStyleSheet(
            QString(
                "QPlainTextEdit {"
                "    background-color: %1;"
                "    color: %2;"
                "    selection-background-color: %3;"
                "    selection-color: %4;"
                "}")
                .arg(baseColor.name(),
                     textColor.name(),
                     selectionColor.name(),
                     selectedTextColor.name()));
    }

    updateCompletionListStyle();

    // 悬浮诊断卡片是独立的 Tool 顶层窗口，主题改变时不会自动继承
    // 编辑器的样式，因此需要显式同步。
    if (diagnosticHoverPopup)
    {
        applyDiagnosticHoverTheme(diagnosticHoverSeverity);
        diagnosticHoverPopup->update();
    }

    // Theme/font formatting must not discard diagnostic ranges. Re-apply the
    // existing selections so their wave underlines repaint immediately.
    updateExtraSelections();
    viewport()->update();

    const QList<CppHighlighter *> highlighters =
        document()->findChildren<CppHighlighter *>();

    CppHighlighter *largeDocumentHighlighter = nullptr;
    for (CppHighlighter *highlighter : highlighters)
    {
        if (!highlighter)
        {
            continue;
        }

        if (m_largeDocumentMode)
        {
            highlighter->setDarkTheme(darkTheme, false);
            largeDocumentHighlighter = highlighter;
        }
        else
        {
            highlighter->setDarkTheme(darkTheme);
        }
    }

    if (largeDocumentHighlighter)
    {
        if (m_largeFileLoading)
        {
            m_largeThemeRefreshPending = true;
        }
        else
        {
            scheduleLargeThemeRehighlight(largeDocumentHighlighter);
        }
    }

    highlightCurrentLine();
    updateExtraSelections();
    lineNumberArea->update();

    if (m_miniMap)
    {
        m_miniMap->updateMarkers();
        m_miniMap->update();
    }

    if (!m_largeDocumentMode)
    {
        style()->unpolish(this);
        style()->polish(this);
    }
    viewport()->update();
    update();
}

void CodeEditor::setBreakpoints(const QSet<int> &lines)
{
    breakpointLines = lines;
    lineNumberArea->update();
}

void CodeEditor::addBreakpoint(int line)
{
    breakpointLines.insert(line);
    lineNumberArea->update();
    emit breakpointToggled(line, true);
}

void CodeEditor::removeBreakpoint(int line)
{
    breakpointLines.remove(line);
    lineNumberArea->update();
    emit breakpointToggled(line, false);
}

void CodeEditor::toggleBreakpoint(int line)
{
    if (line < 1)
    {
        return;
    }

    if (breakpointLines.contains(line))
    {
        breakpointLines.remove(line);
    }
    else
    {
        breakpointLines.insert(line);
    }

    if (lineNumberArea)
    {
        lineNumberArea->update();
    }

    bool added = breakpointLines.contains(line);
    QTimer::singleShot(0, this, [this, line, added]()
                       {
                           emit breakpointToggled(line, added);
                       });
}

bool CodeEditor::hasBreakpoint(int line) const
{
    return breakpointLines.contains(line);
}

void CodeEditor::setCurrentDebugLine(int line)
{
    currentDebugLine = line;

    if (line > 0)
    {
        QTextBlock block = document()->findBlockByLineNumber(line - 1);
        if (block.isValid())
        {
            QTextCursor cursor(block);
            setTextCursor(cursor);
            centerCursor();
        }
    }

    updateExtraSelections();
    lineNumberArea->update();
}

void CodeEditor::clearCurrentDebugLine()
{
    currentDebugLine = -1;
    updateExtraSelections();
    lineNumberArea->update();
}

void CodeEditor::wheelEvent(QWheelEvent *event)
{
    if (event->modifiers() & Qt::ControlModifier)
    {
        const QPoint angleDelta = event->angleDelta();

        if (!angleDelta.isNull())
        {
            QFont currentFont = font();
            int currentSize = currentFont.pointSize();

            if (currentSize < 1)
            {
                currentSize = 11;
            }

            int newSize = currentSize;
            if (angleDelta.y() > 0)
{
                newSize = qMin(currentSize + 1, 72);
            }
            else if (angleDelta.y() < 0)
            {
                newSize = qMax(currentSize - 1, 6);
            }

            if (newSize != currentSize)
            {
                currentFont.setPointSize(newSize);
                setEditorFont(currentFont);
                emit fontSizeChanged(newSize);
            }

            event->accept();
            return;
        }
    }

    QPlainTextEdit::wheelEvent(event);
}

void CodeEditor::drawBreakpointMarker(QPainter &painter, const QRect &rect, bool isCurrentLine)
{
    int size = qMin(rect.width(), rect.height()) - 4;
    int x = rect.left() + (rect.width() - size) / 2;
    int y = rect.top() + (rect.height() - size) / 2;

    painter.setRenderHint(QPainter::Antialiasing);
    painter.setPen(Qt::NoPen);
    painter.setBrush(QColor(255, 60, 60));
    painter.drawEllipse(x, y, size, size);

    if (isCurrentLine)
    {
        painter.setBrush(QColor(255, 255, 0));
        QPolygon arrow;
        int arrowSize = size / 2;
        int cx = x + size / 2;
        int cy = y + size / 2;
        arrow << QPoint(cx - arrowSize / 2, cy - arrowSize / 2)
              << QPoint(cx + arrowSize / 2, cy)
              << QPoint(cx - arrowSize / 2, cy + arrowSize / 2);
        painter.drawPolygon(arrow);
    }
}

int CodeEditor::lineNumberAreaWidth()
{
    int breakpointAreaWidth = 20;

    if (!lineNumbers)
    {
        return breakpointAreaWidth;
    }

    int digits = 1;
    int max = qMax(1, blockCount());
    while (max >= 10)
    {
        max /= 10;
        ++digits;
    }

    int space = breakpointAreaWidth + 10 + fontMetrics().horizontalAdvance(QLatin1Char('9')) * digits;
    return space;
}

void CodeEditor::updateLineNumberAreaWidth(int)
{
    const int miniMapWidth = 18;
    setViewportMargins(lineNumberAreaWidth(), 0, miniMapWidth, 0);

}

void CodeEditor::updateLineNumberArea(const QRect &rect, int dy)
{
    if (dy)
    {
        lineNumberArea->scroll(0, dy);
    }
    else
    {
        lineNumberArea->update(0, rect.y(), lineNumberArea->width(), rect.height());
    }

    if (rect.contains(viewport()->rect()))
    {
        updateLineNumberAreaWidth(0);
    }
}

void CodeEditor::setLspDiagnosticSelections(const QList<QTextEdit::ExtraSelection> &selections)
{
    lspDiagnosticSelections = selections;
    updateExtraSelections();
}

void CodeEditor::clearLspDiagnosticSelections()
{
    lspDiagnosticSelections.clear();
    lspDiagnostics.clear();
    hideDiagnosticHoverPopup();
    updateExtraSelections();
}

void CodeEditor::ensureDiagnosticHoverPopup()
{
    if (diagnosticHoverPopup)
    {
        return;
    }

    diagnosticHoverPopup = new DiagnosticHoverFrame(
        this,
        Qt::Tool | Qt::FramelessWindowHint | Qt::NoDropShadowWindowHint | Qt::WindowDoesNotAcceptFocus);
    diagnosticHoverPopup->setObjectName("DiagnosticHoverPopup");
    diagnosticHoverPopup->setAttribute(Qt::WA_ShowWithoutActivating, true);
    diagnosticHoverPopup->setAttribute(Qt::WA_TransparentForMouseEvents, true);
    diagnosticHoverPopup->setAttribute(Qt::WA_TranslucentBackground, true);
    diagnosticHoverPopup->setFocusPolicy(Qt::NoFocus);

    QVBoxLayout *layout = new QVBoxLayout(diagnosticHoverPopup);
    // Reserve space for the manually painted shadow around the card.
    layout->setContentsMargins(24, 21, 24, 22);
    layout->setSpacing(7);

    QHBoxLayout *headerLayout = new QHBoxLayout;
    headerLayout->setContentsMargins(0, 0, 0, 0);
    headerLayout->setSpacing(9);

    diagnosticHoverTitle = new QLabel(diagnosticHoverPopup);
    diagnosticHoverTitle->setObjectName("DiagnosticHoverTitle");

    diagnosticHoverSource = new QLabel(diagnosticHoverPopup);
    diagnosticHoverSource->setObjectName("DiagnosticHoverSource");
    diagnosticHoverSource->setAlignment(Qt::AlignCenter);

    headerLayout->addWidget(diagnosticHoverTitle);
    headerLayout->addStretch();
    headerLayout->addWidget(diagnosticHoverSource);

    diagnosticHoverMessage = new QLabel(diagnosticHoverPopup);
    diagnosticHoverMessage->setObjectName("DiagnosticHoverMessage");
    diagnosticHoverMessage->setWordWrap(true);
    diagnosticHoverMessage->setTextFormat(Qt::PlainText);
    diagnosticHoverMessage->setTextInteractionFlags(Qt::NoTextInteraction);
    diagnosticHoverMessage->setMaximumWidth(540);

    layout->addLayout(headerLayout);
    layout->addWidget(diagnosticHoverMessage);

    // The card paints its own shadow inside the translucent window. This avoids
    // top-level QGraphicsEffect clipping/visibility differences on Windows.

    // 使用顶层窗口的 windowOpacity 做淡入，并保留一个最终可见状态兜底。
    diagnosticHoverFadeAnimation = new QPropertyAnimation(diagnosticHoverPopup, "windowOpacity", diagnosticHoverPopup);
    diagnosticHoverFadeAnimation->setDuration(175);
    diagnosticHoverFadeAnimation->setEasingCurve(QEasingCurve::OutCubic);

    applyDiagnosticHoverTheme(DiagnosticInfo::Hint);
    diagnosticHoverPopup->hide();
}

void CodeEditor::hideDiagnosticHoverPopup()
{
    if (diagnosticHoverTimer && diagnosticHoverTimer->isActive())
    {
        diagnosticHoverTimer->stop();
    }

    if (diagnosticHoverFadeAnimation && diagnosticHoverFadeAnimation->state() == QAbstractAnimation::Running)
    {
        diagnosticHoverFadeAnimation->stop();
    }

    diagnosticHoverPendingKey.clear();
    diagnosticHoverVisibleKey.clear();

    if (diagnosticHoverPopup)
    {
        diagnosticHoverPopup->hide();
        diagnosticHoverPopup->setWindowOpacity(1.0);
    }
}

QString CodeEditor::diagnosticHoverKey(const QList<DiagnosticInfo> &diagnostics) const
{
    QStringList parts;
    parts.reserve(diagnostics.size());

    for (const DiagnosticInfo &info : diagnostics)
    {
        parts.append(QStringLiteral("%1|%2|%3|%4|%5|%6|%7")
                         .arg(info.startLine)
                         .arg(info.startColumn)
                         .arg(info.endLine)
                         .arg(info.endColumn)
                         .arg(static_cast<int>(info.severity))
                         .arg(info.source)
                         .arg(info.message));
    }

    parts.sort(Qt::CaseSensitive);
    return parts.join(QChar(0x001F));
}

void CodeEditor::scheduleDiagnosticHover(const QList<DiagnosticInfo> &diagnostics,
                                         const QPoint &globalPos)
{
    if (diagnostics.isEmpty() || !diagnosticHoverTimer)
    {
        hideDiagnosticHoverPopup();
        return;
    }

    const QString key = diagnosticHoverKey(diagnostics);

    // 已经显示的是同一组诊断时，不因鼠标在同一个标识符内轻微移动而反复闪烁。
    if (diagnosticHoverPopup && diagnosticHoverPopup->isVisible() &&
        key == diagnosticHoverVisibleKey)
    {
        return;
    }

    // 同一诊断的延迟计时已经开始时，也不要因 1~2 像素移动重新计时。
    if (diagnosticHoverTimer->isActive() && key == diagnosticHoverPendingKey)
    {
        Q_UNUSED(globalPos);
        return;
    }

    if (diagnosticHoverPopup && diagnosticHoverPopup->isVisible())
    {
        if (diagnosticHoverFadeAnimation && diagnosticHoverFadeAnimation->state() == QAbstractAnimation::Running)
        {
            diagnosticHoverFadeAnimation->stop();
        }
        diagnosticHoverPopup->hide();
        diagnosticHoverPopup->setWindowOpacity(1.0);
        diagnosticHoverVisibleKey.clear();
    }

    diagnosticHoverTimer->stop();
    diagnosticHoverPendingKey = key;
    diagnosticHoverTimer->start();
}

void CodeEditor::applyDiagnosticHoverTheme(DiagnosticInfo::Severity severity)
{
    if (!diagnosticHoverPopup)
    {
        return;
    }

    diagnosticHoverSeverity = severity;

    QString severityColor;
    switch (severity)
    {
    case DiagnosticInfo::Error:
        severityColor = QStringLiteral("#F14C4C");
        break;
    case DiagnosticInfo::Warning:
        severityColor = QStringLiteral("#D7A600");
        break;
    case DiagnosticInfo::Info:
        severityColor = QStringLiteral("#3794FF");
        break;
    case DiagnosticInfo::Hint:
    default:
        severityColor = QStringLiteral("#4EC9B0");
        break;
    }

    QString background;
    QString border;
    QString messageColor;
    QString sourceColor;
    QString sourceBackground;
    QString sourceBorder;

    if (themeMode == ThemeMode::Dark)
    {
        background = QStringLiteral("#252526");
        border = QStringLiteral("#747A84");
        messageColor = QStringLiteral("#ECECEC");
        sourceColor = QStringLiteral("#C9E6F7");
        sourceBackground = QStringLiteral("#31343A");
        sourceBorder = QStringLiteral("#4A4F57");
    }
    else if (themeMode == ThemeMode::EyeCare)
    {
        background = QStringLiteral("#FDF6E3");
        border = QStringLiteral("#B49D60");
        messageColor = QStringLiteral("#3B3A32");
        sourceColor = QStringLiteral("#45624A");
        sourceBackground = QStringLiteral("#EFE3C2");
        sourceBorder = QStringLiteral("#C7B98E");
    }
    else
    {
        background = QStringLiteral("#FFFFFF");
        border = QStringLiteral("#AEB8C4");
        messageColor = QStringLiteral("#202124");
        sourceColor = QStringLiteral("#005A9E");
        sourceBackground = QStringLiteral("#F2F6FA");
        sourceBorder = QStringLiteral("#D4DDE6");
    }

    const QColor shadowColor = themeMode == ThemeMode::Dark
                                   ? QColor(0, 0, 0, 170)
                                   : QColor(45, 50, 60, 105);

    // Draw the card, border and shadow ourselves so the result is independent
    // of native tooltip/window-manager painting.
    diagnosticHoverPopup->setCardColors(QColor(background),
                                         QColor(border),
                                         QColor(severityColor),
                                         shadowColor);

    diagnosticHoverTitle->setStyleSheet(
        QString("QLabel { color: %1; background: transparent; border: none; "
                "font-weight: 700; font-size: 10.5pt; }")
            .arg(severityColor));

    diagnosticHoverMessage->setStyleSheet(
        QString("QLabel { color: %1; background: transparent; border: none; "
                "font-size: 9.5pt; padding-top: 1px; }")
            .arg(messageColor));

    diagnosticHoverSource->setStyleSheet(
        QString("QLabel { color: %1; background-color: %2; border: 1px solid %3; "
                "border-radius: 6px; padding: 2px 8px; font-size: 8.5pt; }")
            .arg(sourceColor, sourceBackground, sourceBorder));

    diagnosticHoverPopup->update();
}

QList<CodeEditor::DiagnosticInfo> CodeEditor::diagnosticsAtViewportPoint(const QPoint &viewportPos) const
{
    QList<DiagnosticInfo> result;
    if (!viewport() || !viewport()->rect().contains(viewportPos))
    {
        return result;
    }

    // QPlainTextEdit::cursorForPosition() gives a QTextCursor, i.e. a position
    // BETWEEN characters. That is unsuitable as a direct hit-test for a
    // half-open diagnostic range [startColumn, endColumn): on the right half of
    // a one-character token it can resolve to endColumn and miss completely.
    // Use it only to locate the text block, then hit-test the diagnostic's
    // actual painted x-range.
    QTextCursor nearest = cursorForPosition(viewportPos);
    if (nearest.isNull())
    {
        return result;
    }

    const QTextBlock block = nearest.block();
    if (!block.isValid())
    {
        return result;
    }

    const QRectF blockRect = blockBoundingGeometry(block).translated(contentOffset());
    if (viewportPos.y() < blockRect.top() || viewportPos.y() >= blockRect.bottom())
    {
        return result;
    }

    const int hoverLine = block.blockNumber() + 1;
    const QString blockText = block.text();
    const qreal mouseX = viewportPos.x();

    auto appendUnique = [&result](const DiagnosticInfo &info)
    {
        for (const DiagnosticInfo &existing : result)
        {
            if (existing.message == info.message &&
                existing.source == info.source &&
                existing.severity == info.severity &&
                existing.startLine == info.startLine &&
                existing.startColumn == info.startColumn &&
                existing.endLine == info.endLine &&
                existing.endColumn == info.endColumn)
            {
                return;
            }
        }
        result.append(info);
    };

    const auto isTokenChar = [](QChar c)
    {
        return c.isLetterOrNumber() || c == QLatin1Char('_');
    };

    auto hitDiagnostic = [&](const DiagnosticInfo &info, bool compilerDiagnostic) -> bool
    {
        const int startLine = info.startLine;
        const int endLine = info.endLine > 0 ? info.endLine : startLine;
        if (startLine <= 0 || hoverLine < startLine || hoverLine > endLine)
        {
            return false;
        }

        // If the compiler did not provide a column, limit the hover target to
        // the painted text instead of the whole empty area to the right.
        if (info.startColumn < 0)
        {
            if (hoverLine != startLine || blockText.isEmpty())
            {
                return false;
            }
            const qreal left = blockTextPositionX(block, 0) - 2.0;
            const qreal right = blockTextPositionX(block, blockText.size()) + 2.0;
            return mouseX >= qMin(left, right) && mouseX <= qMax(left, right);
        }

        int rangeStart = (hoverLine == startLine) ? info.startColumn : 0;
        int rangeEnd = (hoverLine == endLine && info.endColumn >= 0)
                           ? info.endColumn
                           : blockText.size();

        rangeStart = qBound(0, rangeStart, blockText.size());
        rangeEnd = qBound(0, rangeEnd, blockText.size());
        if (rangeEnd <= rangeStart)
        {
            rangeEnd = qMin(blockText.size(), rangeStart + 1);
        }

        // GCC/MSVC commonly provides only a single source column. Match the
        // whole identifier token, consistent with the visual wave underline.
        if (compilerDiagnostic && startLine == endLine &&
            rangeEnd <= rangeStart + 1 && rangeStart < blockText.size() &&
            isTokenChar(blockText.at(rangeStart)))
        {
            while (rangeStart > 0 && isTokenChar(blockText.at(rangeStart - 1)))
            {
                --rangeStart;
            }
            rangeEnd = qMax(rangeEnd, rangeStart + 1);
            while (rangeEnd < blockText.size() && isTokenChar(blockText.at(rangeEnd)))
            {
                ++rangeEnd;
            }
        }

        if (rangeStart >= blockText.size())
        {
            return false;
        }

        const qreal x1 = blockTextPositionX(block, rangeStart);
        const qreal x2 = blockTextPositionX(block, rangeEnd);
        const qreal left = qMin(x1, x2) - 2.0;
        const qreal right = qMax(x1, x2) + 2.0;
        return mouseX >= left && mouseX <= right;
    };

    for (const DiagnosticInfo &info : buildDiagnostics)
    {
        if (hitDiagnostic(info, true))
        {
            appendUnique(info);
        }
    }

    for (const DiagnosticInfo &info : lspDiagnostics)
    {
        if (hitDiagnostic(info, false))
        {
            appendUnique(info);
        }
    }

    return result;
}

QList<CodeEditor::DiagnosticInfo> CodeEditor::diagnosticsAtPosition(int line, int column) const
{
    QList<DiagnosticInfo> result;

    auto appendUnique = [&result](const DiagnosticInfo &info)
    {
        for (const DiagnosticInfo &existing : result)
        {
            if (existing.message == info.message &&
                existing.source == info.source &&
                existing.severity == info.severity &&
                existing.startLine == info.startLine &&
                existing.startColumn == info.startColumn &&
                existing.endLine == info.endLine &&
                existing.endColumn == info.endColumn)
            {
                return;
            }
        }
        result.append(info);
    };

    auto containsPosition = [](const DiagnosticInfo &info, int hoverLine, int hoverColumn) -> bool
    {
        const int startLine = info.startLine;
        const int endLine = info.endLine > 0 ? info.endLine : startLine;
        if (startLine <= 0 || hoverLine < startLine || hoverLine > endLine)
        {
            return false;
        }

        // 编译器没有给出列号时，只能退化为整行命中。
        if (info.startColumn < 0)
        {
            return hoverLine == startLine;
        }

        if (startLine == endLine)
        {
            const int rangeEnd = info.endColumn > info.startColumn
                                     ? info.endColumn
                                     : info.startColumn + 1;
            // LSP ranges are end-exclusive. Do not add a +/-1 tolerance here:
            // adjacent diagnostics must never steal each other's message.
            return hoverColumn >= info.startColumn && hoverColumn < rangeEnd;
        }

        if (hoverLine == startLine && hoverColumn < info.startColumn)
        {
            return false;
        }
        if (hoverLine == endLine && info.endColumn >= 0 && hoverColumn >= info.endColumn)
        {
            return false;
        }
        return true;
    };

    for (const DiagnosticInfo &info : buildDiagnostics)
    {
        bool matches = containsPosition(info, line, column);

        // GCC/MSVC diagnostics commonly report only one source column. The
        // visual underline is expanded to the token, so make hover use that same
        // token extent instead of requiring the mouse to sit on one exact column.
        if (!matches && info.startLine == line && info.startColumn >= 0 &&
            info.endLine == info.startLine && info.endColumn == info.startColumn + 1)
        {
            QTextBlock block = document()->findBlockByNumber(line - 1);
            if (block.isValid())
            {
                const QString text = block.text();
                const auto isTokenChar = [](QChar c)
                {
                    return c.isLetterOrNumber() || c == QLatin1Char('_');
                };

                int left = qBound(0, info.startColumn, text.size());
                int right = left;
                if (left < text.size() && isTokenChar(text.at(left)))
                {
                    while (left > 0 && isTokenChar(text.at(left - 1)))
                    {
                        --left;
                    }
                    right = qMax(right + 1, info.startColumn + 1);
                    while (right < text.size() && isTokenChar(text.at(right)))
                    {
                        ++right;
                    }
                    matches = column >= left && column < right;
                }
            }
        }

        if (matches)
        {
            appendUnique(info);
        }
    }

    for (const DiagnosticInfo &info : lspDiagnostics)
    {
        if (containsPosition(info, line, column))
        {
            appendUnique(info);
        }
    }

    return result;
}

void CodeEditor::showDiagnosticHoverPopup(const QList<DiagnosticInfo> &diagnostics,
                                          const QPoint &globalPos)
{
    if (diagnostics.isEmpty())
    {
        hideDiagnosticHoverPopup();
        return;
    }

    ensureDiagnosticHoverPopup();

    DiagnosticInfo::Severity highestSeverity = DiagnosticInfo::Hint;
    auto severityRank = [](DiagnosticInfo::Severity severity)
    {
        switch (severity)
        {
        case DiagnosticInfo::Error:
            return 4;
        case DiagnosticInfo::Warning:
            return 3;
        case DiagnosticInfo::Info:
            return 2;
        case DiagnosticInfo::Hint:
        default:
            return 1;
        }
    };

    QStringList sources;
    QStringList messages;
    for (const DiagnosticInfo &info : diagnostics)
    {
        if (severityRank(info.severity) > severityRank(highestSeverity))
        {
            highestSeverity = info.severity;
        }

        const QString source = info.source.trimmed().isEmpty() ? tr("诊断") : info.source.trimmed();
        if (!sources.contains(source))
        {
            sources.append(source);
        }

        QString message = info.message.trimmed();
        if (message.isEmpty())
        {
            message = tr("未提供详细诊断信息");
        }

        if (!messages.contains(message))
        {
            messages.append(message);
        }
    }

    QString severityText;
    switch (highestSeverity)
    {
    case DiagnosticInfo::Error:
        severityText = tr("错误");
        break;
    case DiagnosticInfo::Warning:
        severityText = tr("警告");
        break;
    case DiagnosticInfo::Info:
        severityText = tr("信息");
        break;
    case DiagnosticInfo::Hint:
    default:
        severityText = tr("提示");
        break;
    }

    diagnosticHoverTitle->setText(
        diagnostics.size() > 1
            ? tr("%1 · %2 条诊断").arg(severityText).arg(diagnostics.size())
            : severityText);
    diagnosticHoverSource->setText(sources.join(QStringLiteral(" · ")));
    diagnosticHoverMessage->setText(messages.join(QStringLiteral("\n\n")));

    applyDiagnosticHoverTheme(highestSeverity);

    diagnosticHoverPopup->adjustSize();
    QSize popupSize = diagnosticHoverPopup->sizeHint().expandedTo(QSize(285, 0));
    popupSize.setWidth(qMin(popupSize.width(), 580));
    popupSize.setHeight(qMin(popupSize.height(), 330));
    diagnosticHoverPopup->resize(popupSize);

    QPoint popupPos = globalPos + QPoint(15, 21);
    QScreen *screen = QGuiApplication::screenAt(globalPos);
    if (!screen)
    {
        screen = QGuiApplication::primaryScreen();
    }
    if (screen)
    {
        const QRect available = screen->availableGeometry();
        if (popupPos.x() + popupSize.width() > available.right())
        {
            popupPos.setX(qMax(available.left(), globalPos.x() - popupSize.width() - 15));
        }
        if (popupPos.y() + popupSize.height() > available.bottom())
        {
            popupPos.setY(qMax(available.top(), globalPos.y() - popupSize.height() - 15));
        }
    }

    diagnosticHoverPopup->move(popupPos);
    // Never start at absolute zero: on some Windows/Qt combinations an
    // opacity-0 top-level tool window can fail to repaint when the animation
    // begins. Keep it faintly visible, then fade to 1.0.
    diagnosticHoverPopup->setWindowOpacity(0.08);
    diagnosticHoverPopup->show();
    diagnosticHoverPopup->raise();

    diagnosticHoverVisibleKey = diagnosticHoverKey(diagnostics);
    diagnosticHoverPendingKey.clear();

    if (diagnosticHoverFadeAnimation)
    {
        diagnosticHoverFadeAnimation->stop();
        diagnosticHoverFadeAnimation->setStartValue(0.08);
        diagnosticHoverFadeAnimation->setEndValue(1.0);
        diagnosticHoverFadeAnimation->start();

        QPointer<DiagnosticHoverFrame> popupGuard(diagnosticHoverPopup);
        QTimer::singleShot(230, diagnosticHoverPopup, [popupGuard]()
                           {
                               if (popupGuard && popupGuard->isVisible())
                               {
                                   // Visibility fallback if the platform did not advance
                                   // windowOpacity animation for a tool window.
                                   popupGuard->setWindowOpacity(1.0);
                                   popupGuard->update();
                               }
                           });
    }
    else
    {
        diagnosticHoverPopup->setWindowOpacity(1.0);
    }
}

void CodeEditor::rebuildBuildDiagnosticSelections()
{
    buildDiagnosticSelections.clear();

    for (const DiagnosticInfo &info : buildDiagnostics)
    {
        if (info.startLine <= 0)
        {
            continue;
        }

        QTextBlock block = document()->findBlockByNumber(info.startLine - 1);
        if (!block.isValid())
        {
            continue;
        }

        const QString blockText = block.text();
        if (blockText.isEmpty())
        {
            continue;
        }

        int startColumn = info.startColumn;
        if (startColumn < 0)
        {
            startColumn = 0;
            while (startColumn < blockText.size() && blockText.at(startColumn).isSpace())
            {
                ++startColumn;
            }
        }
        startColumn = qBound(0, startColumn, qMax(0, blockText.size() - 1));

        int endColumn = -1;
        if (info.endLine == info.startLine && info.endColumn > startColumn)
        {
            endColumn = qMin(info.endColumn, blockText.size());
        }
        else
        {
            endColumn = startColumn + 1;
            const auto isTokenChar = [](QChar c)
            {
                return c.isLetterOrNumber() || c == QLatin1Char('_');
            };

            if (startColumn < blockText.size() && isTokenChar(blockText.at(startColumn)))
            {
                while (endColumn < blockText.size() && isTokenChar(blockText.at(endColumn)))
                {
                    ++endColumn;
                }
            }
        }

        endColumn = qBound(startColumn + 1, endColumn, blockText.size());

QTextCursor cursor(document());
        cursor.setPosition(block.position() + startColumn);
        cursor.setPosition(block.position() + endColumn, QTextCursor::KeepAnchor);

        QTextEdit::ExtraSelection selection;
        selection.cursor = cursor;
        selection.format.setUnderlineStyle(QTextCharFormat::WaveUnderline);

        switch (info.severity)
        {
        case DiagnosticInfo::Error:
            selection.format.setUnderlineColor(QColor("#F14C4C"));
            break;
        case DiagnosticInfo::Warning:
            selection.format.setUnderlineColor(QColor("#CCA700"));
            break;
        case DiagnosticInfo::Info:
            selection.format.setUnderlineColor(QColor("#3794FF"));
            break;
        case DiagnosticInfo::Hint:
        default:
            selection.format.setUnderlineColor(QColor("#4EC9B0"));
            break;
        }

        buildDiagnosticSelections.append(selection);
    }
}

void CodeEditor::setBuildDiagnostics(const QList<DiagnosticInfo> &diagnostics)
{
    buildDiagnostics = diagnostics;
    rebuildBuildDiagnosticSelections();
    hideDiagnosticHoverPopup();
    updateExtraSelections();

    // 如果诊断到达时鼠标已经停在对应代码上，不要求用户再晃一下鼠标。
    QTimer::singleShot(0, this, [this]()
                       {
                           if (!viewport())
                           {
                               return;
                           }
                           const QPoint globalPos = QCursor::pos();
                           const QPoint viewportPos = viewport()->mapFromGlobal(globalPos);
                           if (!viewport()->rect().contains(viewportPos))
                           {
                               return;
                           }
                           const QList<DiagnosticInfo> current = diagnosticsAtViewportPoint(viewportPos);
                           if (!current.isEmpty())
                           {
                               scheduleDiagnosticHover(current, globalPos);
                           }
                       });
}

void CodeEditor::clearBuildDiagnostics()
{
    if (buildDiagnostics.isEmpty() && buildDiagnosticSelections.isEmpty())
    {
        return;
    }

    buildDiagnostics.clear();
    buildDiagnosticSelections.clear();
    hideDiagnosticHoverPopup();
    updateExtraSelections();
}

void CodeEditor::setLspDiagnostics(const QList<DiagnosticInfo> &diagnostics)
{
    lspDiagnostics = diagnostics;
    hideDiagnosticHoverPopup();

    // clangd 是异步返回的：诊断更新时鼠标可能已经静止在问题代码上。
    // 重新检查当前鼠标位置，让延迟悬浮窗仍能自然出现。
    QTimer::singleShot(0, this, [this]()
                       {
                           if (!viewport())
                           {
                               return;
                           }
                           const QPoint globalPos = QCursor::pos();
                           const QPoint viewportPos = viewport()->mapFromGlobal(globalPos);
                           if (!viewport()->rect().contains(viewportPos))
                           {
                               return;
                           }
                           const QList<DiagnosticInfo> current = diagnosticsAtViewportPoint(viewportPos);
                           if (!current.isEmpty())
                           {
                               scheduleDiagnosticHover(current, globalPos);
                           }
                       });
}

void CodeEditor::resizeEvent(QResizeEvent *event)
{
    QPlainTextEdit::resizeEvent(event);
    QRect cr = contentsRect();
    int lineNumWidth = lineNumberAreaWidth();
    lineNumberArea->setGeometry(QRect(cr.left(), cr.top(), lineNumWidth, cr.height()));

    if (m_miniMap)
    {
        const int barWidth = 18;
        const QRect viewRect = viewport()->geometry();
        const int x = viewRect.right() + 1;
        const int y = viewRect.top();
        const int h = viewRect.height();
        m_miniMap->setGeometry(x, y, barWidth, h);
        m_miniMap->raise();
    }

}

bool CodeEditor::isPositionInCommentOrString() const
{
    QTextCursor cursor = textCursor();
    int position = cursor.position();
    QString fullText = toPlainText().left(position);

    bool inString = false;
    bool inChar = false;
    bool inBlockComment = false;
    bool escaped = false;

    for (int i = 0; i < fullText.length(); ++i)
    {
        QChar c = fullText[i];

        if (escaped)
        {
            escaped = false;
            continue;
        }

        if (c == '\\')
        {
            escaped = true;
            continue;
        }

        if (!inBlockComment)
        {
            if (c == '"' && !inChar)
            {
                inString = !inString;
            }
            else if (c == '\'' && !inString)
            {
                inChar = !inChar;
            }
        }

        if (!inString && !inChar)
        {
            if (!inBlockComment && c == '/' && i + 1 < fullText.length() && fullText[i + 1] == '*')
            {
                inBlockComment = true;
                i++;
                continue;
            }
            if (inBlockComment && c == '*' && i + 1 < fullText.length() && fullText[i + 1] == '/')
            {
                inBlockComment = false;
                i++;
                continue;
            }
        }
    }

    return inString || inChar || inBlockComment;
}

void CodeEditor::setEditorFont(const QFont &font)
{
    qDebug() << "[CodeEditor] 应用字体:" << font.family() << font.pointSize();

    QFont editorFont = font;
    if (editorFont.pointSize() < 1 && editorFont.pixelSize() < 1)
    {
        editorFont.setPointSize(11);
    }

    QPlainTextEdit::setFont(editorFont);
    document()->setDefaultFont(editorFont);
    updateFontDependentLayout();
}

void CodeEditor::updateFontDependentLayout()
{
    const int safeIndentSize = qMax(1, indentSize);
    const QFontMetricsF metrics(font());
    const qreal spaceWidth = qMax<qreal>(1.0, metrics.horizontalAdvance(QLatin1Char(' ')));
    const qreal newTabStopDistance = qMax<qreal>(1.0, safeIndentSize * spaceWidth);

    if (!qFuzzyCompare(tabStopDistance() + 1.0, newTabStopDistance + 1.0))
    {
        setTabStopDistance(newTabStopDistance);
    }

    updateLineNumberAreaWidth(0);
    document()->markContentsDirty(0, document()->characterCount());
    viewport()->update();

    if (lineNumberArea)
    {
        lineNumberArea->update();
    }

    if (m_miniMap)
    {
        m_miniMap->update();
    }

    QTimer::singleShot(0, this, [this]()
    {
        viewport()->update();
        if (lineNumberArea)
        {
            lineNumberArea->update();
        }

        if (m_largeDocumentMode && !m_largeFileLoading)
        {
            startLargeFileWidthScan();
        }
    });
}

int CodeEditor::leadingIndentColumns(const QTextBlock &block) const
{
    const QString text = block.text();
    const int safeIndentSize = qMax(1, indentSize);
    int columns = 0;

    for (const QChar character : text)
    {
        if (character == QLatin1Char(' '))
        {
            ++columns;
        }
        else if (character == QLatin1Char('\t'))
        {
            columns = ((columns / safeIndentSize) + 1) * safeIndentSize;
        }
        else
        {
            break;
        }
    }

    return columns;
}

qreal CodeEditor::blockTextPositionX(const QTextBlock &block, int characterOffset) const
{
    QTextCursor blockCursor(block);
    const qreal blockStartX = cursorRect(blockCursor).left();
    QTextLayout *layout = block.layout();

    if (!layout || layout->lineCount() < 1)
    {
        return blockStartX;
    }

    const int textLength = static_cast<int>(block.text().size());
    const int boundedOffset = qBound(0, characterOffset, textLength);
    QTextLine line = layout->lineForTextPosition(boundedOffset);

    if (!line.isValid())
    {
        line = layout->lineAt(0);
    }

    const qreal lineStartX = line.cursorToX(line.textStart());
    const qreal positionX = line.cursorToX(boundedOffset);
    return blockStartX + positionX - lineStartX;
}

qreal CodeEditor::indentGuideX(const QTextBlock &block, int visualColumn) const
{
    const QString text = block.text();
    const int safeIndentSize = qMax(1, indentSize);
    int columns = 0;

    for (int characterIndex = 0; characterIndex < text.size(); ++characterIndex)
    {
        const QChar character = text.at(characterIndex);

        if (character == QLatin1Char(' '))
        {
            ++columns;
        }
        else if (character == QLatin1Char('\t'))
        {
            columns = ((columns / safeIndentSize) + 1) * safeIndentSize;
        }
        else
        {
            break;
        }

        if (columns >= visualColumn)
        {
            return blockTextPositionX(block, characterIndex + 1);
        }
    }

    const qreal blockStartX = blockTextPositionX(block, 0);
    return blockStartX +
           (static_cast<qreal>(visualColumn) / safeIndentSize) * tabStopDistance();
}

void CodeEditor::highlightCurrentLine()
{
    updateExtraSelections();
}

void CodeEditor::updateExtraSelections()
{
    QList<QTextEdit::ExtraSelection> extraSelections;

    if (!isReadOnly())
    {
        QTextEdit::ExtraSelection currentLineSelection;
        QColor lineColor;
        if (themeMode == ThemeMode::Dark)
        {
            lineColor = QColor("#2D2D2D");
        }
        else if (themeMode == ThemeMode::EyeCare)
        {
            lineColor = QColor("#F8EFCF");
        }
        else
        {
            lineColor = QColor("#F0F0F0");
        }

        currentLineSelection.format.setBackground(lineColor);
        currentLineSelection.format.setProperty(QTextFormat::FullWidthSelection, true);
        currentLineSelection.cursor = textCursor();
        currentLineSelection.cursor.clearSelection();

        int currentLine = textCursor().blockNumber() + 1;
        if (currentLine != errorLine && currentLine != warningLine)
        {
            extraSelections.append(currentLineSelection);
        }
    }

    if (errorLine > 0)
    {
        QTextBlock block = document()->findBlockByNumber(errorLine - 1);
        if (block.isValid())
        {
            QTextEdit::ExtraSelection errorSelection;
            errorSelection.format.setBackground(errorBgColor);
            errorSelection.format.setProperty(QTextFormat::FullWidthSelection, true);
            errorSelection.cursor = QTextCursor(block);
            errorSelection.cursor.clearSelection();
            extraSelections.append(errorSelection);
        }
    }

    if (warningLine > 0)
    {
        QTextBlock block = document()->findBlockByNumber(warningLine - 1);
        if (block.isValid())
        {
            QTextEdit::ExtraSelection warningSelection;
            warningSelection.format.setBackground(warningBgColor);
            warningSelection.format.setProperty(QTextFormat::FullWidthSelection, true);
            warningSelection.cursor = QTextCursor(block);
            warningSelection.cursor.clearSelection();
            extraSelections.append(warningSelection);
        }
    }

    if (currentDebugLine > 0)
    {
QTextBlock block = document()->findBlockByNumber(currentDebugLine - 1);
        if (block.isValid())
        {
            QTextEdit::ExtraSelection debugSelection;
            debugSelection.format.setBackground(QColor(255, 255, 150));
            debugSelection.format.setProperty(QTextFormat::FullWidthSelection, true);
            debugSelection.cursor = QTextCursor(block);
            debugSelection.cursor.clearSelection();
            extraSelections.append(debugSelection);
        }
    }

    extraSelections.append(matchSelections);
    extraSelections.append(buildDiagnosticSelections);
    extraSelections.append(lspDiagnosticSelections);

    setExtraSelections(extraSelections);
}

void CodeEditor::lineNumberAreaPaintEvent(QPaintEvent *event)
{
    QPainter painter(lineNumberArea);

    painter.setFont(this->font());

    QColor backgroundColor, textColor, currentLineColor;
    if (themeMode == ThemeMode::Dark)
    {
        backgroundColor = QColor("#2D2D2D");
        textColor = QColor("#969696");
        currentLineColor = QColor("#3C3C3C");
    }
    else if (themeMode == ThemeMode::EyeCare)
    {
        backgroundColor = QColor("#F3E8C8");
        textColor = QColor("#746F61");
        currentLineColor = QColor("#E9DDBB");
    }
    else
    {
        backgroundColor = QColor("#F5F5F5");
        textColor = QColor("#646464");
        currentLineColor = QColor("#E6E6E6");
    }

    painter.fillRect(event->rect(), backgroundColor);

    QTextBlock block = firstVisibleBlock();
    int blockNumber = block.blockNumber();
    int top = (int)blockBoundingGeometry(block).translated(contentOffset()).top();
    int bottom = top + (int)blockBoundingRect(block).height();

    int breakpointAreaWidth = 20;
    int lineNumberWidth = lineNumberArea->width() - breakpointAreaWidth;

    while (block.isValid() && top <= event->rect().bottom())
    {
        if (block.isVisible() && bottom >= event->rect().top())
        {
            int lineNumber = blockNumber + 1;
            bool isCurrentDebug = (lineNumber == currentDebugLine);
            bool hasBreakpointHere = breakpointLines.contains(lineNumber);

            if (isCurrentDebug)
            {
                painter.fillRect(QRect(0, top, lineNumberArea->width(), fontMetrics().height()),
                                 QColor(255, 255, 0, 50));
            }

            if (hasBreakpointHere || isCurrentDebug)
            {
                QRect markerRect(0, top, breakpointAreaWidth, fontMetrics().height());

                if (hasBreakpointHere)
                {
                    int size = qMin(breakpointAreaWidth, fontMetrics().height()) - 4;
                    int x = (breakpointAreaWidth - size) / 2;
                    int y = top + (fontMetrics().height() - size) / 2;

                    painter.setRenderHint(QPainter::Antialiasing);
                    painter.setPen(Qt::NoPen);
                    painter.setBrush(QColor(255, 60, 60));
                    painter.drawEllipse(x, y, size, size);
                }

                if (isCurrentDebug)
                {
                    int arrowSize = 8;
                    int cx = breakpointAreaWidth / 2;
                    int cy = top + fontMetrics().height() / 2;

                    painter.setBrush(QColor(255, 220, 0));
                    painter.setPen(QPen(QColor(200, 150, 0), 1));

                    QPolygon arrow;
                    arrow << QPoint(cx - 3, cy - arrowSize / 2)
                          << QPoint(cx + arrowSize / 2, cy)
                          << QPoint(cx - 3, cy + arrowSize / 2);
                    painter.drawPolygon(arrow);
                }
            }

            if (lineNumbers)
            {
                QString number = QString::number(lineNumber);
                painter.setPen(isCurrentDebug ? QColor(0, 0, 0) : textColor);
                painter.drawText(breakpointAreaWidth, top, lineNumberWidth - 4,
                                 fontMetrics().height(),
                                 Qt::AlignRight, number);
            }
        }

        block = block.next();
        top = bottom;
        bottom = top + (int)blockBoundingRect(block).height();
        ++blockNumber;
    }
}

void CodeEditor::mousePressEvent(QMouseEvent *event)
{
    hideDiagnosticHoverPopup();

    if (completionPopup && completionPopup->isVisible())
    {
        QRect popupRect = completionPopup->geometry();
        QPoint globalClickPos = mapToGlobal(event->pos());

        if (!popupRect.contains(globalClickPos))
        {
            hideCompletion();
        }
    }

    QPlainTextEdit::mousePressEvent(event);

    emit cursorPositionChanged();
}

void CodeEditor::mouseMoveEvent(QMouseEvent *event)
{
    QPlainTextEdit::mouseMoveEvent(event);

    if (event->buttons() != Qt::NoButton ||
        (completionPopup && completionPopup->isVisible()))
    {
        hideDiagnosticHoverPopup();
        return;
    }

    const QList<DiagnosticInfo> diagnostics =
        diagnosticsAtViewportPoint(event->position().toPoint());
    if (!diagnostics.isEmpty())
    {
        scheduleDiagnosticHover(diagnostics, event->globalPosition().toPoint());
        return;
    }

    hideDiagnosticHoverPopup();
}

void CodeEditor::leaveEvent(QEvent *event)
{
    hideDiagnosticHoverPopup();
    QPlainTextEdit::leaveEvent(event);
}

void CodeEditor::paintEvent(QPaintEvent *event)
{
    QPlainTextEdit::paintEvent(event);

    if (!showIndentGuides || indentSize < 1)
    {
        return;
    }

    QPainter painter(viewport());
    painter.setRenderHint(QPainter::Antialiasing, false);
    painter.setClipRect(event->rect());

    QColor guideColor;
    if (themeMode == ThemeMode::Dark)
    {
        guideColor = QColor(105, 105, 105, 190);
    }
    else if (themeMode == ThemeMode::EyeCare)
    {
        guideColor = QColor(155, 145, 120, 170);
    }
    else
    {
        guideColor = QColor(175, 175, 175, 180);
    }

    const qreal devicePixelRatio = qMax<qreal>(1.0, viewport()->devicePixelRatioF());
    QPen guidePen(guideColor);
    guidePen.setStyle(Qt::SolidLine);
    guidePen.setWidthF(1.0 / devicePixelRatio);
    painter.setPen(guidePen);

    QTextBlock block = firstVisibleBlock();
    const QPointF offset = contentOffset();

    while (block.isValid())
    {
        const QRectF blockGeometry = blockBoundingGeometry(block).translated(offset);
        const QRectF blockRect = blockBoundingRect(block);
        const qreal top = blockGeometry.top();
        const qreal bottom = top + blockRect.height();

        if (top > event->rect().bottom())
        {
            break;
        }

        if (bottom >= event->rect().top())
        {
            const QString text = block.text();
            const bool isBlank = text.trimmed().isEmpty();
            int drawDepth = 0;

            if (!isBlank)
            {
                drawDepth = leadingIndentColumns(block);
            }
            else
            {
                QTextBlock previousBlock = block.previous();
                while (previousBlock.isValid() && previousBlock.text().trimmed().isEmpty())
                {
                    previousBlock = previousBlock.previous();
                }

                QTextBlock nextBlock = block.next();
                while (nextBlock.isValid() && nextBlock.text().trimmed().isEmpty())
                {
                    nextBlock = nextBlock.next();
                }

                int previousIndent = 0;
                int nextIndent = 0;

                if (previousBlock.isValid())
                {
                    previousIndent = leadingIndentColumns(previousBlock);
                    if (previousBlock.text().trimmed().endsWith(QLatin1Char('{')))
                    {
                        previousIndent += indentSize;
                    }
                }

                if (nextBlock.isValid())
                {
                    nextIndent = leadingIndentColumns(nextBlock);
                    if (nextBlock.text().trimmed().startsWith(QLatin1Char('}')))
                    {
                        nextIndent += indentSize;
                    }
                }

                drawDepth = qMin(previousIndent, nextIndent);
            }

            qreal firstContentX = 0.0;
            if (!isBlank)
            {
                int firstContentOffset = 0;
                while (firstContentOffset < text.size())
                {
                    const QChar character = text.at(firstContentOffset);
                    if (character != QLatin1Char(' ') && character != QLatin1Char('\t'))
                    {
                        break;
                    }
                    ++firstContentOffset;
                }

                firstContentX = blockTextPositionX(block, firstContentOffset);
            }

            for (int column = indentSize; column < drawDepth; column += indentSize)
            {
                const qreal rawX = indentGuideX(block, column);
                const qreal x = (qFloor(rawX * devicePixelRatio) + 0.5) / devicePixelRatio;

                if (x < event->rect().left() - 1.0 || x > event->rect().right() + 1.0)
                {
                    continue;
                }

                if (!isBlank && x >= firstContentX - (1.0 / devicePixelRatio))
                {
                    continue;
                }

                const qreal snappedTop = qCeil(qMax<qreal>(top, event->rect().top()) * devicePixelRatio) / devicePixelRatio;
                const qreal snappedBottom = qFloor(qMin<qreal>(bottom, event->rect().bottom() + 1.0) * devicePixelRatio) / devicePixelRatio;

                if (snappedBottom > snappedTop)
                {
                    painter.drawLine(QPointF(x, snappedTop), QPointF(x, snappedBottom));
                }
            }
        }

        block = block.next();
    }
}

void CodeEditor::handleAutoBrackets(QKeyEvent *event)
{
    QChar key = event->text().isEmpty() ? QChar() : event->text().at(0);
    QTextCursor cursor = textCursor();

    if (key == '(' || key == '[')
    {
        hideCompletion();

        const QChar closing = (key == '(') ? QLatin1Char(')') : QLatin1Char(']');
        if (cursor.hasSelection())
        {
            const QString selected = cursor.selectedText();
            cursor.insertText(QString(key) + selected + QString(closing));
            setTextCursor(cursor);
        }
        else
        {
            cursor.insertText(QString(key) + QString(closing));
            cursor.movePosition(QTextCursor::Left);
            setTextCursor(cursor);
        }
        event->accept();
    }
    else if (key == '{')
    {
        // Curly braces keep the existing indentation/beautification path in keyPressEvent().
        event->ignore();
    }
    else if (key == ')' || key == ']' || key == '}')
    {
        hideCompletion();

        if (key == '}')
        {
            QTextCursor testCursor = textCursor();
            QTextBlock block = testCursor.block();
            QString text = block.text();
            QString trimmed = text.trimmed();

            if (trimmed == "}" || trimmed.isEmpty())
            {
                int targetIndent = 0;
                QTextBlock prevBlock = block.previous();
                while (prevBlock.isValid())
                {
                    if (!prevBlock.text().trimmed().isEmpty())
                    {
                        QString prevText = prevBlock.text();
                        for (int i = 0; i < prevText.length(); ++i)
                        {
                            if (prevText[i] == ' ')
                            {
                                targetIndent++;
                            }
                            else if (prevText[i] == '\t')
                            {
                                targetIndent += indentSize;
                            }
                            else
                            {
                                break;
                            }
                        }
                        break;
                    }
                    prevBlock = prevBlock.previous();
                }

                testCursor.movePosition(QTextCursor::StartOfBlock);
                testCursor.movePosition(QTextCursor::EndOfBlock, QTextCursor::KeepAnchor);

                QString newLine = indentationTextForColumns(targetIndent);
                newLine.append('}');
                testCursor.insertText(newLine);

                if (document()->characterAt(testCursor.position()) == '}')
                {
                    testCursor.deleteChar();
                }

                setTextCursor(testCursor);
                event->accept();
                return;
            }
        }

        QTextCursor skipCursor = textCursor();
        if (skipCursor.hasSelection())
        {
            event->ignore();
            return;
        }

        QChar nextChar = document()->characterAt(skipCursor.position());
        if (nextChar == key)
        {
            skipCursor.movePosition(QTextCursor::Right);
            setTextCursor(skipCursor);
            event->accept();
        }
        else
        {
            if (key == '}')
            {
                skipCursor.insertText("}");
                event->accept();
            }
            else
            {
                event->ignore();
            }
        }
    }
    else
    {
        event->ignore();
    }
}

void CodeEditor::handleAutoQuotes(QKeyEvent *event)
{
    QChar key = event->text().isEmpty() ? QChar() : event->text().at(0);
    if (key != QLatin1Char('"') && key != QLatin1Char('\''))
    {
        event->ignore();
        return;
    }

    hideCompletion();
    QTextCursor cursor = textCursor();

    if (cursor.hasSelection())
    {
        const QString selected = cursor.selectedText();
        cursor.insertText(QString(key) + selected + QString(key));
        setTextCursor(cursor);
        event->accept();
        return;
    }

    // If an auto-inserted/typed quote already exists at the caret, move over it.
    if (document()->characterAt(cursor.position()) == key)
    {
        cursor.movePosition(QTextCursor::Right);
        setTextCursor(cursor);
        event->accept();
        return;
    }

    cursor.insertText(QString(key) + QString(key));
    cursor.movePosition(QTextCursor::Left);
    setTextCursor(cursor);
    event->accept();
}

void CodeEditor::handleAutoIndent()
{
    QTextCursor cursor = textCursor();
    QTextBlock currentBlock = cursor.block();
    QTextBlock previousBlock = currentBlock.previous();

    if (!previousBlock.isValid())
    {
        return;
    }

    QString previousText = previousBlock.text();
    int indentLevel = 0;

    for (int i = 0; i < previousText.length(); ++i)
    {
        if (previousText[i] == QLatin1Char(' '))
        {
            ++indentLevel;
        }
        else if (previousText[i] == QLatin1Char('\t'))
        {
            const int safeIndentSize = qMax(1, indentSize);
            indentLevel = ((indentLevel / safeIndentSize) + 1) * safeIndentSize;
        }
        else
        {
            break;
        }
    }

    QString currentLineText = currentBlock.text();
    bool hasClosingBrace = currentLineText.trimmed() == "}";
    QString trimmedPrevious = previousText.trimmed();

    if (trimmedPrevious.endsWith('{') && !hasClosingBrace)
    {
        indentLevel += qMax(1, indentSize);
    }

    if (indentLevel > 0)
    {
        cursor.insertText(indentationTextForColumns(indentLevel));
    }

    if (hasClosingBrace && trimmedPrevious.endsWith('}'))
    {
        QTextBlock block = cursor.block();
        QString blockText = block.text();
        int removeCount = 0;

        if (!blockText.isEmpty() && blockText.at(0) == QLatin1Char('\t'))
        {
            removeCount = 1;
        }
        else
        {
            const int safeIndentSize = qMax(1, indentSize);
            while (removeCount < qMin(safeIndentSize, blockText.size()) &&
                   blockText.at(removeCount) == QLatin1Char(' '))
            {
                ++removeCount;
            }
        }

        if (removeCount > 0)
        {
            QTextCursor editCursor(block);
            editCursor.movePosition(QTextCursor::Right, QTextCursor::KeepAnchor, removeCount);
            editCursor.removeSelectedText();
        }
    }
}

class CompilerIDE;
class NewFileDialog;
class WelcomeDialog;
