CompilerIDE::~CompilerIDE()
{
    qApp->removeEventFilter(this);
    stopCompetitiveCompanionServer();
    if (compileProcess)
    {
        compileProcess->kill();
        compileProcess->waitForFinished();
        delete compileProcess;
    }
    if (runProcess)
    {
        runProcess->kill();
        runProcess->waitForFinished();
        delete runProcess;
    }

    const QList<DWORD> managedTaskIds = managedRunTasks.keys();
    for (DWORD processId : managedTaskIds)
    {
        terminateManagedRunTask(processId);
    }

    for (const QString &executable : m_concurrentBuildExecutables)
    {
        QFile::remove(executable);
    }

    if (hRunningProcess != NULL)
    {
        TerminateProcess(hRunningProcess, 0);
        WaitForSingleObject(hRunningProcess, 1000);
        CloseHandle(hRunningProcess);
        hRunningProcess = NULL;
    }

    if (m_lspClient)
    {
        m_lspClient->stopServerAndWait(3000);
        delete m_lspClient;
        m_lspClient = nullptr;
    }

    const QSet<QString> cleanupDirectories = m_lspFlagDirs;
    for (const QString &dir : cleanupDirectories)
    {
        removeOwnedCompileFlags(dir);
    }
    m_lspOwnedFiles.clear();
    m_lspFlagDirs.clear();

    QApplication::processEvents(QEventLoop::AllEvents, 100);
    QThread::msleep(50);

    if (debugger->isRunning())
    {
        debugger->stopDebugging();
    }
    if (errorTableContextMenu)
    {
        delete errorTableContextMenu;
    }
    if (diagnosticsTimer)
    {
        diagnosticsTimer->stop();
        delete diagnosticsTimer;
    }

    cleanupCharts();

    delete debugger;
    delete codeCompleter;
    delete terminal;
    delete snippetManager;
}

