void CompilerIDE::showFloatingMessage(const QString &message, int duration, bool isError)
{
    QLabel *label = new QLabel(this);
    label->setText(message);
    label->setAlignment(Qt::AlignCenter);
    label->setWordWrap(true);
    label->setMaximumWidth(600);

    QString bgColor, textColor, borderColor;
    if (isError)
    {
        if (darkTheme)
        {
            bgColor = "#8B0000";
            textColor = "white";
            borderColor = "#FF6B6B";
        }
        else
        {
            bgColor = "#dc3545";
            textColor = "white";
            borderColor = "#ff6b6b";
        }
    }
    else
    {
        if (darkTheme)
        {
            bgColor = "#1e7e34";
            textColor = "white";
            borderColor = "#5cb85c";
        }
        else
        {
            bgColor = "#28a745";
            textColor = "white";
            borderColor = "#5cb85c";
        }
    }

    label->setStyleSheet(QString(
                             "QLabel {"
                             "    background-color: %1;"
                             "    color: %2;"
                             "    font-size: 14px;"
                             "    font-weight: bold;"
                             "    padding: 10px 20px;"
                             "    border-radius: 8px;"
                             "    border: 2px solid %3;"
                             "}")
                             .arg(bgColor, textColor, borderColor));
    label->adjustSize();

    int x = width() - label->width() - 20;
    int y = 20;
    label->move(x, y);
    label->raise();
    label->show();

    QGraphicsOpacityEffect *effect = new QGraphicsOpacityEffect(label);
    label->setGraphicsEffect(effect);

    QPropertyAnimation *fadeIn = new QPropertyAnimation(effect, "opacity");
    fadeIn->setDuration(300);
    fadeIn->setStartValue(0.0);
    fadeIn->setEndValue(1.0);
    fadeIn->setEasingCurve(QEasingCurve::OutCubic);
    fadeIn->start();

    QTimer::singleShot(duration - 300, label, [label, effect]()
                       {
                           QPropertyAnimation *fadeOut = new QPropertyAnimation(effect, "opacity");
                           fadeOut->setDuration(300);
                           fadeOut->setStartValue(1.0);
                           fadeOut->setEndValue(0.0);
                           fadeOut->setEasingCurve(QEasingCurve::InCubic);
                           connect(fadeOut, &QPropertyAnimation::finished, label, &QLabel::deleteLater);
                           fadeOut->start();
                       });
}

void CompilerIDE::toggleBreakpoint()
{
    CodeEditor *editor = currentEditor();
    if (!editor)
    {
        return;
    }

    QTextCursor cursor = editor->textCursor();
    int line = cursor.blockNumber() + 1;

    QString filePath = curFile;
    if (filePath.isEmpty())
    {
        return;
    }

    if (editor->hasBreakpoint(line))
    {
        editor->removeBreakpoint(line);
        debugger->removeBreakpoint(filePath, line);
    }
    else
    {
        editor->addBreakpoint(line);
        debugger->setBreakpoint(filePath, line);
    }
}


void CompilerIDE::showEvent(QShowEvent *event)
{
    QMainWindow::showEvent(event);

    if (!property("sidebarInitialExpandDone").toBool())
    {
        if (rightSidebar)
        {
            QString targetFeature;

            for (const QString &feature : sidebarFeatureNames)
            {
                if (m_visibleSidebarFeatureNames.contains(feature) &&
                    rightSidebar->isFeatureEnabled(feature))
                {
                    targetFeature = feature;
                    break;
                }
            }

            if (targetFeature.isEmpty() && !sidebarFeatureNames.isEmpty())
            {
                targetFeature = sidebarFeatureNames.first();
            }

            if (!targetFeature.isEmpty())
            {
                rightSidebar->switchToFeature(targetFeature);
            }
        }

        setProperty("sidebarInitialExpandDone", true);
    }

    QTimer::singleShot(200, this, [this]()
    {
        qDebug() << "\n=== 修复光标 ===";

        while (QApplication::overrideCursor())
        {
            QApplication::restoreOverrideCursor();
        }

        QList<QWidget *> widgets = this->findChildren<QWidget *>();

        qDebug() << "总共找到" << widgets.size() << "个子控件";

        int waitCursorCount = 0;

        for (QWidget *widget : widgets)
        {
            Qt::CursorShape shape = widget->cursor().shape();

            if (shape == Qt::WaitCursor || shape == Qt::BusyCursor)
            {
                qDebug() << "发现等待光标:"
                         << widget->metaObject()->className()
                         << "对象名:" << widget->objectName()
                         << "光标形状:" << shape;

                waitCursorCount++;
            }
        }

        qDebug() << "发现" << waitCursorCount << "个等待光标";

        for (QWidget *widget : widgets)
        {
            widget->unsetCursor();
        }

        this->unsetCursor();

        CodeEditor *editor = currentEditor();

        if (editor)
        {
            editor->setCursor(Qt::IBeamCursor);
            qDebug() << "编辑器光标已设置为 IBeam";
        }

        qDebug() << "=== 修复完成 ===\n";
    });
}

void CompilerIDE::runToCursor()
{
    CodeEditor *editor = currentEditor();
    if (!editor || !debugger->isRunning())
    {
        return;
    }

    QTextCursor cursor = editor->textCursor();
    int line = cursor.blockNumber() + 1;

    QString filePath = curFile;
    if (filePath.isEmpty())
    {
        return;
    }

    debugger->runToCursor(filePath, line);
}

