        iconLabel->setStyleSheet(
            "background: qlineargradient(x1:0, y1:0, x2:1, y2:1,"
            "stop:0 #2E86AB, stop:0.55 #A23B72, stop:1 #F18F01);"
            "border-radius: 20px;"
            "color: white; font-size: 20px; font-weight: bold;");
